```python
import sys
import re
from collections import Counter

def count_words(filename):
 """Return a Counter of word frequencies in the given file."""
 try:
 with open(filename, 'r', encoding='utf-8') as f:
 text = f.read().lower()
 # Extract words: sequences of letters and numbers (ignore punctuation)
 words = re.findall(r'\b\w+\b', text)
 return Counter(words)
 except FileNotFoundError:
 print(f"Error: file '{filename}' not found.")
 return Counter()

def main():
 if len(sys.argv) != 2:
 print("Usage: python word_freq.py <text_file>")
 sys.exit(1)

 filename = sys.argv[1]
 counter = count_words(filename)

 # Print frequencies sorted by count (descending)
 for word, freq in counter.most_common():
 print(f"{word}: {freq}")

if __name__ == "__main__":
 main()
```

